/**
 * Schema 3.1 numeric input at the API boundary.
 *
 * Legacy calculations still consume ``inputs`` internally.  The adapter
 * below converts these values while preserving their declared units for
 * validation and reporting.
 */
export interface TypedInputValue {
  unit: string;
  value: number;
}

/**
 * Compatibility adapter for existing Schema 3.2 calculation modules.
 */
export interface TypedModuleInputs {
  module: "steel_beam" | "steel_column" | "portal_frame" | "concrete_beam" | "concrete_slab" | "concrete_column" | "spread_footing" | "strip_footing" | "timber_beam" | "timber_column" | "steel_baseplate_anchor" | "timber_deck_panel" | "steel_cantilever_post" | "masonry_wall" | "rc_wall" | "retaining_wall";
  values?: Record<string, TypedInputValue | string | boolean>;
}

